import { useState, useEffect } from "react";

const API_BASE = "http://127.0.0.1:8000/api";

const authHeaders = () => ({
  "Content-Type": "application/json",
});

// ── Status badge ──────────────────────────────────────────────
function StatusBadge({ status }) {
  const map = {
    applied: { bg: "#e0f2fe", color: "#0369a1", label: "Applied" },
    shortlisted: { bg: "#dcfce7", color: "#15803d", label: "Shortlisted" },
    rejected: { bg: "#fee2e2", color: "#b91c1c", label: "Rejected" },
    hired: { bg: "#f3e8ff", color: "#7e22ce", label: "Hired" },
    interview: { bg: "#fef9c3", color: "#92400e", label: "Interview" },
  };
  const s = map[status?.toLowerCase()] || {
    bg: "#f1f5f9",
    color: "#475569",
    label: status || "Unknown",
  };
  return (
    <span
      style={{
        background: s.bg,
        color: s.color,
        padding: "3px 10px",
        borderRadius: 99,
        fontSize: 12,
        fontWeight: 600,
        letterSpacing: 0.3,
      }}
    >
      {s.label}
    </span>
  );
}

// ── Single candidate card ─────────────────────────────────────
function CandidateCard({ candidate, onDownload, downloading }) {
  const fullName =
    candidate.full_name ||
    `${candidate.first_name || ""} ${candidate.last_name || ""}`.trim() ||
    "Unknown Candidate";

  const email = candidate.email || "—";
  const phone = candidate.phone || candidate.phone_number || "—";
  const status = candidate.application_status || candidate.status || "applied";
  const jobTitle = candidate.job_title || candidate.position || "—";
  const hasResume = !!(candidate.resume || candidate.resume_url || candidate.cv);

  return (
    <div
      style={{
        background: "#fff",
        border: "1px solid #e8edf3",
        borderRadius: 14,
        padding: "22px 24px",
        display: "flex",
        alignItems: "center",
        gap: 20,
        boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
        transition: "box-shadow 0.2s, transform 0.2s",
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.boxShadow = "0 6px 20px rgba(0,0,0,0.09)";
        e.currentTarget.style.transform = "translateY(-1px)";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.boxShadow = "0 2px 8px rgba(0,0,0,0.04)";
        e.currentTarget.style.transform = "translateY(0)";
      }}
    >
      {/* Avatar */}
      <div
        style={{
          width: 48,
          height: 48,
          borderRadius: "50%",
          background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "#fff",
          fontWeight: 700,
          fontSize: 18,
          flexShrink: 0,
        }}
      >
        {fullName.charAt(0).toUpperCase()}
      </div>

      {/* Info */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ fontWeight: 700, fontSize: 15, color: "#0f172a" }}>{fullName}</span>
          <StatusBadge status={status} />
        </div>
        <div style={{ fontSize: 13, color: "#64748b", marginTop: 4 }}>
          {jobTitle !== "—" && (
            <span style={{ marginRight: 14 }}>💼 {jobTitle}</span>
          )}
          <span style={{ marginRight: 14 }}>✉️ {email}</span>
          {phone !== "—" && <span>📞 {phone}</span>}
        </div>
      </div>

      {/* Download button */}
      <button
        onClick={() => hasResume && onDownload(candidate)}
        disabled={!hasResume || downloading === candidate.id}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "9px 18px",
          borderRadius: 9,
          border: "none",
          background: hasResume
            ? downloading === candidate.id
              ? "#94a3b8"
              : "linear-gradient(135deg, #6366f1, #8b5cf6)"
            : "#e2e8f0",
          color: hasResume ? "#fff" : "#94a3b8",
          fontWeight: 600,
          fontSize: 13,
          cursor: hasResume && downloading !== candidate.id ? "pointer" : "not-allowed",
          flexShrink: 0,
          transition: "opacity 0.15s",
        }}
        onMouseEnter={(e) => hasResume && (e.currentTarget.style.opacity = "0.88")}
        onMouseLeave={(e) => (e.currentTarget.style.opacity = "1")}
        title={!hasResume ? "No resume uploaded" : "Download resume"}
      >
        {downloading === candidate.id ? (
          <>
            <span style={{ animation: "spin 1s linear infinite", display: "inline-block" }}>⟳</span>
            Downloading…
          </>
        ) : (
          <>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
              <polyline points="7 10 12 15 17 10" />
              <line x1="12" y1="15" x2="12" y2="3" />
            </svg>
            {hasResume ? "Resume" : "No Resume"}
          </>
        )}
      </button>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────
export default function CandidateResumes() {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [downloading, setDownloading] = useState(null);
  const [toast, setToast] = useState(null);

  // ── Fetch candidates ───────────────────────────────────────
  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = async () => {
    setLoading(true);
    setError("");
    try {
      const profilesRes = await fetch("http://127.0.0.1:8000/api/candidates/");
      if (!profilesRes.ok) throw new Error(`HTTP ${profilesRes.status}`);
      const profilesJson = await profilesRes.json();
      const profiles = Array.isArray(profilesJson) ? profilesJson : profilesJson.results || [];

      const resumesRes = await fetch("http://127.0.0.1:8000/api/resumes/");
      const resumesJson = resumesRes.ok ? await resumesRes.json() : [];
      const resumes = Array.isArray(resumesJson) ? resumesJson : resumesJson.results || [];

      const merged = profiles.map((candidate) => {
        const candidateResumes = resumes.filter((r) => r.candidate === candidate.id);
        const primaryResume = candidateResumes.find((r) => r.is_primary) || candidateResumes[0];
        return {
          ...candidate,
          resume: primaryResume ? "http://127.0.0.1:8000" + primaryResume.file : null,
          resume_title: primaryResume?.title || null,
        };
      });

      setCandidates(merged);
    } catch (e) {
      setError("Could not load candidates. Make sure backend is running. " + e.message);
    } finally {
      setLoading(false);
    }
  };


  // ── Download resume ────────────────────────────────────────
  const handleDownload = async (candidate) => {
    setDownloading(candidate.id);
    try {
      const resumeUrl =
        candidate.resume || candidate.resume_url || candidate.cv;

      // If it's a relative path, prepend base URL
      const fullUrl = resumeUrl.startsWith("http")
        ? resumeUrl
        : `http://127.0.0.1:8000${resumeUrl}`;

      const res = await fetch(fullUrl);
      if (!res.ok) throw new Error("Download failed");

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;

      // Determine filename
      const fullName =
        candidate.full_name ||
        `${candidate.first_name || ""} ${candidate.last_name || ""}`.trim() ||
        "candidate";
      const ext = resumeUrl.split(".").pop().split("?")[0] || "pdf";
      a.download = `${fullName.replace(/\s+/g, "_")}_resume.${ext}`;

      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(url);

      showToast(`✅ Downloaded resume for ${fullName}`);
    } catch (e) {
      showToast(`❌ Failed: ${e.message}`, true);
    } finally {
      setDownloading(null);
    }
  };

  const showToast = (msg, isError = false) => {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), 3500);
  };

  // ── Filter ─────────────────────────────────────────────────
  const filtered = candidates.filter((c) => {
    const name = (
      c.full_name ||
      `${c.first_name || ""} ${c.last_name || ""}`.trim()
    ).toLowerCase();
    const email = (c.email || "").toLowerCase();
    const q = search.toLowerCase();
    const matchSearch = !q || name.includes(q) || email.includes(q);
    const matchStatus =
      statusFilter === "all" ||
      (c.application_status || c.status || "").toLowerCase() === statusFilter;
    return matchSearch && matchStatus;
  });

  const withResume = filtered.filter(
    (c) => c.resume || c.resume_url || c.cv
  ).length;

  // ── Render ─────────────────────────────────────────────────
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#f8fafc",
        fontFamily: "'Segoe UI', system-ui, sans-serif",
        padding: "32px 24px",
      }}
    >
      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes slideIn { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
      `}</style>

      {/* Toast */}
      {toast && (
        <div
          style={{
            position: "fixed",
            bottom: 28,
            right: 28,
            background: toast.isError ? "#fee2e2" : "#dcfce7",
            color: toast.isError ? "#b91c1c" : "#15803d",
            border: `1px solid ${toast.isError ? "#fca5a5" : "#86efac"}`,
            borderRadius: 12,
            padding: "14px 20px",
            fontWeight: 600,
            fontSize: 14,
            boxShadow: "0 8px 30px rgba(0,0,0,0.12)",
            zIndex: 9999,
            animation: "slideIn 0.3s ease",
          }}
        >
          {toast.msg}
        </div>
      )}

      <div style={{ maxWidth: 860, margin: "0 auto" }}>
        {/* Header */}
        <div style={{ marginBottom: 28 }}>
          <h1
            style={{
              fontSize: 26,
              fontWeight: 800,
              color: "#0f172a",
              margin: 0,
              letterSpacing: -0.5,
            }}
          >
            Candidate Resumes
          </h1>
          <p style={{ color: "#64748b", margin: "6px 0 0", fontSize: 14 }}>
            Browse and download applicant resumes
          </p>
        </div>

        {/* Stats bar */}
        {!loading && !error && (
          <div
            style={{
              display: "flex",
              gap: 16,
              marginBottom: 24,
              flexWrap: "wrap",
            }}
          >
            {[
              { label: "Total Candidates", value: candidates.length, color: "#6366f1" },
              { label: "With Resume", value: candidates.filter((c) => c.resume || c.resume_url || c.cv).length, color: "#10b981" },
              { label: "Showing", value: filtered.length, color: "#f59e0b" },
            ].map((s) => (
              <div
                key={s.label}
                style={{
                  background: "#fff",
                  border: "1px solid #e8edf3",
                  borderRadius: 10,
                  padding: "12px 20px",
                  flex: 1,
                  minWidth: 120,
                }}
              >
                <div style={{ fontSize: 22, fontWeight: 800, color: s.color }}>{s.value}</div>
                <div style={{ fontSize: 12, color: "#94a3b8", marginTop: 2 }}>{s.label}</div>
              </div>
            ))}
          </div>
        )}

        {/* Filters */}
        <div
          style={{
            display: "flex",
            gap: 12,
            marginBottom: 20,
            flexWrap: "wrap",
          }}
        >
          <input
            type="text"
            placeholder="🔍  Search by name or email…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{
              flex: 1,
              minWidth: 220,
              padding: "10px 14px",
              borderRadius: 10,
              border: "1px solid #e2e8f0",
              fontSize: 14,
              outline: "none",
              background: "#fff",
              color: "#0f172a",
            }}
          />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            style={{
              padding: "10px 14px",
              borderRadius: 10,
              border: "1px solid #e2e8f0",
              fontSize: 14,
              background: "#fff",
              color: "#475569",
              outline: "none",
              cursor: "pointer",
            }}
          >
            <option value="all">All Statuses</option>
            <option value="applied">Applied</option>
            <option value="shortlisted">Shortlisted</option>
            <option value="interview">Interview</option>
            <option value="hired">Hired</option>
            <option value="rejected">Rejected</option>
          </select>
          <button
            onClick={fetchCandidates}
            style={{
              padding: "10px 18px",
              borderRadius: 10,
              border: "1px solid #e2e8f0",
              background: "#fff",
              color: "#475569",
              fontSize: 14,
              cursor: "pointer",
              fontWeight: 600,
            }}
          >
            ↻ Refresh
          </button>
        </div>

        {/* Content */}
        {loading ? (
          <div style={{ textAlign: "center", padding: 60, color: "#94a3b8", fontSize: 15 }}>
            <div style={{ fontSize: 32, marginBottom: 12, animation: "spin 1s linear infinite", display: "inline-block" }}>⟳</div>
            <div>Loading candidates…</div>
          </div>
        ) : error ? (
          <div
            style={{
              background: "#fff1f2",
              border: "1px solid #fecdd3",
              borderRadius: 12,
              padding: 24,
              color: "#be123c",
              textAlign: "center",
            }}
          >
            <div style={{ fontSize: 28, marginBottom: 8 }}>⚠️</div>
            <div style={{ fontWeight: 600 }}>{error}</div>
            <button
              onClick={fetchCandidates}
              style={{
                marginTop: 14,
                padding: "8px 20px",
                background: "#be123c",
                color: "#fff",
                border: "none",
                borderRadius: 8,
                cursor: "pointer",
                fontWeight: 600,
              }}
            >
              Retry
            </button>
          </div>
        ) : filtered.length === 0 ? (
          <div style={{ textAlign: "center", padding: 60, color: "#94a3b8" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>📂</div>
            <div style={{ fontWeight: 600, fontSize: 15 }}>No candidates found</div>
            <div style={{ fontSize: 13, marginTop: 4 }}>Try adjusting your search or filter</div>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {filtered.map((c) => (
              <CandidateCard
                key={c.id}
                candidate={c}
                onDownload={handleDownload}
                downloading={downloading}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
